(1,'CYB-2026-00001',5,'Demo User - Aarav Sharma','aarav@demo.test','9100000005','Phishing','[DEMO DATA] Received an SMS claiming my bank account was blocked and clicked the link. The page asked for card details.','2026-08-28','http://secure-login-demo.example/verify',0,NULL,'Low','CLOSED',2,1,'2026-08-29 10:00:00','2026-09-03 11:00:00'),
(2,'CYB-2026-00002',5,'Demo User - Aarav Sharma','aarav@demo.test','9100000005','Online Fraud','[DEMO DATA] A seller on a marketplace asked for an advance payment and stopped responding after the transfer.','2026-09-02',NULL,45000,NULL,'Medium','RESOLVED',3,1,'2026-09-03 10:00:00','2026-09-07 11:00:00'),
(3,'CYB-2026-00003',6,'Demo User - Priya Menon','priya@demo.test','9100000006','Account Compromise','[DEMO DATA] My email account password was changed and messages were sent to my contacts without my knowledge.','2026-09-05',NULL,0,NULL,'Medium','INVESTIGATION',2,1,'2026-09-06 10:00:00','2026-09-09 11:00:00'),
(4,'CYB-2026-00004',6,'Demo User - Priya Menon','priya@demo.test','9100000006','Malware','[DEMO DATA] After installing a free video tool my files were renamed and a message demanded payment to unlock them.','2026-09-08',NULL,0,NULL,'Medium','INVESTIGATION',4,1,'2026-09-09 10:00:00','2026-09-12 11:00:00'),
(5,'CYB-2026-00005',7,'Demo User - Kabir Singh','kabir@demo.test','9100000007','Fake Website','[DEMO DATA] Ordered shoes from a website that looked genuine. The goods never arrived and the site has disappeared.','2026-09-10','http://secure-login-demo.example/verify',12000,NULL,'Medium','ASSIGNED',3,1,'2026-09-11 10:00:00','2026-09-13 11:00:00'),
(6,'CYB-2026-00006',7,'Demo User - Kabir Singh','kabir@demo.test','9100000007','Cyberbullying','[DEMO DATA] Anonymous accounts keep posting abusive comments and edited pictures of me on social media.','2026-09-15',NULL,0,NULL,'Low','UNDER_REVIEW',NULL,1,'2026-09-16 10:00:00','2026-09-17 11:00:00'),
(7,'CYB-2026-00007',8,'Demo User - Isha Patel','isha@demo.test','9100000008','Identity Theft','[DEMO DATA] Found a loan application made in my name that I never submitted. Suspect my documents were leaked.','2026-09-18',NULL,150000,NULL,'High','UNDER_REVIEW',NULL,1,'2026-09-19 10:00:00','2026-09-20 11:00:00'),
(8,'CYB-2026-00008',8,'Demo User - Isha Patel','isha@demo.test','9100000008','Unauthorized Access','[DEMO DATA] Received alerts about logins to my cloud storage from an unknown country and files were deleted.','2026-09-22',NULL,0,NULL,'Medium','SUBMITTED',NULL,1,'2026-09-23 10:00:00','2026-09-23 11:00:00'),
(9,'CYB-2026-00009',9,'Demo User - Neil Fernandes','neil@demo.test','9100000009','Phishing','[DEMO DATA] Received an SMS claiming my bank account was blocked and clicked the link. The page asked for card details.','2026-09-27','http://secure-login-demo.example/verify',2500,NULL,'Low','SUBMITTED',NULL,1,'2026-09-28 10:00:00','2026-09-28 11:00:00'),
